async def calculate_household_impact(data: HouseholdImpactRequest, response: Response, definition: list[str]=Query(default=[], description="<measure id>:<commit>, once per measure: the commit its approved receipt was made at. The answer's definitions give each one's baseline and reform identities recomputed at that commit from this build's code, to compare with the receipt (uk_budget_data.definitions). A query parameter, so the body a build without them refuses is unchanged.")):
