    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    try:
        received = time.perf_counter()
        results, calculating = await anyio.to_thread.run_sync(timed, functools.partial(_household_impact, requested=requested), data, limiter=HOUSEHOLD_REQUESTS)
        response.headers['Server-Timing'] = server_timing(calculating, time.perf_counter() - received - calculating, memory_peak_bytes())
        return results
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except TimeoutError as e:
        raise HTTPException(status_code=504, detail=f'Calculation timed out: {e}')
    except Exception as e:
        raise HTTPException(status_code=500, detail=f'Calculation error: {e}')

