def server_timing(calculating: float, queued: float, peak: Optional[int]) -> str:
    parts = [f'calculate;dur={calculating * 1000:.0f}', f'queue;dur={queued * 1000:.0f}']
    if peak is not None:
        parts.append(f'memory;desc="peak {peak / 2 ** 20:.0f} MiB"')
    return ', '.join(parts)

