def household_workers() -> int:
    configured = os.environ.get('HOUSEHOLD_WORKERS')
    if configured:
        try:
            return max(1, int(configured))
        except ValueError:
            logging.getLogger(__name__).warning('HOUSEHOLD_WORKERS=%r is not a whole number; ignoring it', configured)
    try:
        quota, period = CGROUP_CPU_MAX.read_text().split()[:2]
    except (OSError, ValueError):
        return 1
    if quota == 'max':
        return 1
    return max(1, int(int(quota) // int(period)))

